/* @autogenerated */
import { Component, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { AppStateService } from '@shared/context/state/app-state.service';
import { ANONYMOUS_USER, UserInfo } from '@shared/context/identity/user-info.model';
import { SelectorsOutletComponent } from './selectors-outlet.component';
import { WorkspaceStateService } from './workspace-state.service';

@Component({ selector: 'test-selector', template: '<span class="probe">selector</span>' })
class ProbeSelectorComponent {}

describe('SelectorsOutletComponent', () => {
  it('renders the selectors of the active workspace only with a session', () => {
    const user = signal<UserInfo>(ANONYMOUS_USER);
    TestBed.configureTestingModule({
      providers: [
        { provide: WorkspaceStateService, useValue: { selectors: signal([ProbeSelectorComponent]) } },
        { provide: AppStateService, useValue: { user: () => user } },
      ],
    });
    const fixture = TestBed.createComponent(SelectorsOutletComponent);
    fixture.detectChanges();
    expect(fixture.nativeElement.querySelector('.probe')).toBeNull();

    user.set({ authenticated: true, uid: 'u1' });
    fixture.detectChanges();
    expect(fixture.nativeElement.querySelector('.probe')).not.toBeNull();
  });
});
